import{_ as e,o as i,c as o,ae as l}from"./chunks/framework.vXWZTEWX.js";const p=JSON.parse('{"title":"Documento 00: Análisis Detallado y Viabilidad","description":"","frontmatter":{},"headers":[],"relativePath":"tfm/00_analisis_detallado.md","filePath":"tfm/00_analisis_detallado.md"}'),t={name:"tfm/00_analisis_detallado.md"};function d(n,a,s,r,c,u){return i(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="documento-00-analisis-detallado-y-viabilidad" tabindex="-1">Documento 00: Análisis Detallado y Viabilidad <a class="header-anchor" href="#documento-00-analisis-detallado-y-viabilidad" aria-label="Permalink to &quot;Documento 00: Análisis Detallado y Viabilidad&quot;">​</a></h1><h2 id="_1-resumen-ejecutivo" tabindex="-1">1. Resumen Ejecutivo <a class="header-anchor" href="#_1-resumen-ejecutivo" aria-label="Permalink to &quot;1. Resumen Ejecutivo&quot;">​</a></h2><p>El presente proyecto, <strong>TenderCheck AI</strong>, aborda la problemática de la validación técnica de licitaciones públicas (&quot;Pliegos&quot;). Actualmente, este proceso es manual, lento y propenso a errores humanos, especialmente en la verificación de cumplimiento de requisitos técnicos obligatorios (CRITERIOS DE SOLVENCIA TÉCNICA).</p><p>La solución propuesta es un asistente inteligente basado en <strong>Inteligencia Artificial Local (Ollama/Llama 3)</strong> que automatiza la extracción de requisitos y la validación de ofertas, garantizando la privacidad de los datos y reduciendo el tiempo de revisión en un 80%.</p><h2 id="_2-analisis-del-problema" tabindex="-1">2. Análisis del Problema <a class="header-anchor" href="#_2-analisis-del-problema" aria-label="Permalink to &quot;2. Análisis del Problema&quot;">​</a></h2><h3 id="_2-1-situacion-actual" tabindex="-1">2.1. Situación Actual <a class="header-anchor" href="#_2-1-situacion-actual" aria-label="Permalink to &quot;2.1. Situación Actual&quot;">​</a></h3><ul><li><strong>Volumen</strong>: Las administraciones públicas publican miles de licitaciones anuales.</li><li><strong>Complejidad</strong>: Los pliegos (PDF) tienen estructuras no estandarizadas y lenguaje legal complejo.</li><li><strong>Riesgo</strong>: Un error en la validación puede impugnar un concurso público o adjudicar a un proveedor no cualificado.</li></ul><h3 id="_2-2-necesidad-detectada" tabindex="-1">2.2. Necesidad Detectada <a class="header-anchor" href="#_2-2-necesidad-detectada" aria-label="Permalink to &quot;2.2. Necesidad Detectada&quot;">​</a></h3><p>Se requiere una herramienta que:</p><ol><li>Ingeste documentos PDF masivos.</li><li>Entienda el contexto legal/técnico.</li><li>Extraiga cláusulas de obligado cumplimiento (&quot;Deberá tener...&quot;, &quot;Obligatorio...&quot;).</li><li>Compare estas cláusulas contra la documentación del proveedor.</li></ol><h2 id="_3-estudio-de-viabilidad" tabindex="-1">3. Estudio de Viabilidad <a class="header-anchor" href="#_3-estudio-de-viabilidad" aria-label="Permalink to &quot;3. Estudio de Viabilidad&quot;">​</a></h2><h3 id="_3-1-viabilidad-tecnica" tabindex="-1">3.1. Viabilidad Técnica <a class="header-anchor" href="#_3-1-viabilidad-tecnica" aria-label="Permalink to &quot;3.1. Viabilidad Técnica&quot;">​</a></h3><p>El uso de LLMs (Large Language Models) permite el razonamiento semántico necesario. La viabilidad de usar modelos locales (Llama 3 8B) se ha confirmado mediante pruebas de concepto, logrando una precisión aceptable con técnicas de <em>Prompt Engineering</em> y post-procesado heurístico.</p><h3 id="_3-2-viabilidad-economica" tabindex="-1">3.2. Viabilidad Económica <a class="header-anchor" href="#_3-2-viabilidad-economica" aria-label="Permalink to &quot;3.2. Viabilidad Económica&quot;">​</a></h3><p>El cambio a una arquitectura &quot;Local-First&quot; elimina los costes recurrentes de APIs (OpenAI), haciendo el proyecto sostenible y escalable sin coste por token.</p><h3 id="_3-3-viabilidad-legal-privacidad" tabindex="-1">3.3. Viabilidad Legal/Privacidad <a class="header-anchor" href="#_3-3-viabilidad-legal-privacidad" aria-label="Permalink to &quot;3.3. Viabilidad Legal/Privacidad&quot;">​</a></h3><p>Al procesar los datos en local, se garantiza el cumplimiento estricto del RGPD/GDPR, ya que ningún dato sensible abandona la infraestructura del organismo público.</p>',17)])])}const b=e(t,[["render",d]]);export{p as __pageData,b as default};
